//@category SP11.Camera
import ghidra.app.script.GhidraScript; import ghidra.app.decompiler.*; import ghidra.program.model.listing.*; import ghidra.program.model.symbol.*; import ghidra.program.model.address.*; import java.io.*; import java.util.*;
public class ExtractProtectedGuidXrefs extends GhidraScript { public void run() throws Exception {String[] a=getScriptArgs(); PrintWriter p=new PrintWriter(new FileOutputStream(a[0])); ReferenceManager rm=currentProgram.getReferenceManager(); FunctionManager fm=currentProgram.getFunctionManager(); Address x=toAddr("1813306c8"); p.println("TARGET="+x); LinkedHashSet<Function> roots=new LinkedHashSet<>(); ReferenceIterator ri=rm.getReferencesTo(x); while(ri.hasNext()){Reference r=ri.next(); Function f=fm.getFunctionContaining(r.getFromAddress()); p.println("XREF "+r.getFromAddress()+" function="+(f==null?"":f.getName())+" entry="+(f==null?"":f.getEntryPoint())); if(f!=null)roots.add(f);} LinkedHashSet<Function> all=new LinkedHashSet<>(roots); for(Function f:roots){all.addAll(f.getCallingFunctions(monitor)); all.addAll(f.getCalledFunctions(monitor));} DecompInterface d=new DecompInterface(); d.openProgram(currentProgram); for(Function f:all){p.println("\n//// "+f.getName()+" @"+f.getEntryPoint()+" root="+roots.contains(f)+" ////"); DecompileResults dr=d.decompileFunction(f,180,monitor); if(dr!=null&&dr.decompileCompleted()&&dr.getDecompiledFunction()!=null)p.println(dr.getDecompiledFunction().getC());} d.dispose();p.close();}}
